cy.getByDataCy('reasonForEvaluation').then(function (el) {
    //step 1
    if (el.is(':visible')) {
        cy.wrap(el).type(faker_1.faker.word.words(2));
        cy.wait(1000);
        cy.getByDataCy('next-eval-step');
        cy.get('[data-cy="next-eval-step"] > .sa-button').click().wait(2000);
        cy.getByDataCy('criteria-dropdowns');
    }
    //step 2
    cy.getByDataCy('criteria-dropdowns').then(function (el) {
        if (el.is(':visible')) {
            cy.getByDataCy('criteria-dropdowns').each(function (el, index) {
                cy.getByDataCy('criteria-dropdowns').eq(index).click().as('list');
                cy.wait(500);
                cy.get('@list').find('.dropdown-btn span').eq(0).then(function (el) {
                    cy.get('@list').find('.dropdown-list .item2>li>[type="checkbox"]').eq(0).scrollIntoView().check({ force: true });
                    cy.getByDataCy('criteria-dropdowns').eq(index).click({ force: true }).wait(500);
                });
                cy.wait(1000);
            });
        }
    });
    //step 3
    cy.contains('Evaluate').click().wait(5000);
    cy.get('sa-button').contains('Complete').click().wait(1000);
});

