    url: "https://complytek-testing-api.regtek.co/api/reportFilters/filter?customFilters={%22isClient%22:null,%22isArchived%22:false,%22isDeleted%22:false,%22clientTypes%22:[1,2],%22regulationGroups%22:[1],%22subGroups%22:null}&skip=0&take=50&requireTotalCount=true&_=1728980328740",
    headers: {
        'Content-Type': 'application/json',
        'Authorization': "Bearer ".concat(user_token)
    }
}).then(function (response) {
    userId = response.body.data[0].id;
    if (userId) {
        cy.wait(2000);
        cy.request({
            method: "POST",
            url: "https://complytek-testing-api.regtek.co/api/IkycCalls/transactionScreening",
            body: {
                "swiftMt": "",
                "sepa": "",
                "iso2022": "",
                "paymentDescriptionDetails": "",
                "citiesMatchPercentage": 80,
                "internalBlacklistsMatchPercentage": 80,
                "transactionReference": "REF001",
                "checkExistingScreening": "",
                "fastPayment": "",
                "clientRegulationGroupId": 1,
                "clientId": userId,
                "retrieveFullScreeningDetails": "",
                "personEntities": [],
                "corporateEntities": [
                    {
                        "address": "",
                        "capacity": "",
                        "country": "",
                        "name": "Test LLC"
                    }
                ],
                "unspecifiedEntities": [],
                "countriesCheck": [],
                "citiesCheck": [],
                "restrictedCountries": [],
                "restrictedCities": []
            },
            headers: {
                'Content-Type': 'application/json',
                'Authorization': "Bearer ".concat(user_token)
            }
        }).then(function (res) {
            case_Id = res.body.caseId;
            if (case_Id) {
                cy.visit("/main/client-individual/".concat(userId, "/1/transaction-screening-case/").concat(case_Id)).wait(5000);
                cy.contains(case_Id);
            }
        });
    }
});

